import{_ as e,o as i,c as o,a3 as r}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Input / Output / Merge Priority Theory: A Brief Explanation","description":"","frontmatter":{"translationSource":{"title":"优先输入/输出/汇入理论简要说明","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AA41FJVehHzDTC97GcFV5F","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/input-output-merge-priority-theory"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/input-output-merge-priority-theory"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/input-output-merge-priority-theory"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/input-output-merge-priority-theory"}]]},"headers":[],"relativePath":"input-output-merge-priority-theory.md","filePath":"logistics/src/page-AA41FJVehHzDTC97GcFV5F.md"}'),n={name:"input-output-merge-priority-theory.md"};function a(s,t,l,p,u,d){return i(),o("div",null,[...t[0]||(t[0]=[r('<div class="logistics-content"><h1 id="input-output-merge-priority-theory-a-brief-explanation" tabindex="-1">Input / Output / Merge Priority Theory: A Brief Explanation <a class="header-anchor" href="#input-output-merge-priority-theory-a-brief-explanation" aria-label="Permalink to &quot;Input / Output / Merge Priority Theory: A Brief Explanation&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-14T07-40-38-165Z-a1e1e549" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-14. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-14T07:40:39.277Z">2026-11-14</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>AA41FJVehHzDTC97GcFV5F</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AA41FJVehHzDTC97GcFV5F" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>This page mainly helps readers unfamiliar with basic input/output priorities who find <a href="/endfield-skydoc/introduction-to-analyzing-endfield-logistics-bugs">Introduction to Analyzing Endfield Logistics Bugs</a> difficult to read directly.</p><p><span id="source-block-LStqO3ihrJjZA2Uyti9bzr"></span></p><h2 id="output-priority-protocol-stash–converger-conduit-outlet-manifold–converger" tabindex="-1">Output Priority: Protocol Stash–Converger / Conduit Outlet Manifold–Converger <a class="header-anchor" href="#output-priority-protocol-stash–converger-conduit-outlet-manifold–converger" aria-label="Permalink to &quot;Output Priority: Protocol Stash–Converger / Conduit Outlet Manifold–Converger&quot;">​</a></h2><p><img src="/endfield-skydoc/logistics/src/assets/images/img-158b774bfb7274dc.q90-a0e442d04c7e3c73.webp" alt="Input / Output / Merge Priority Theory: A Brief Explanation"></p><p>In brief, placing a Protocol Stash / Conduit Outlet Manifold flush against a converger creates output priority. Count the belts/pipes and logistics components on both routes—their damping. The route with fewer outputs first; the one with more outputs second.</p><p><span class="mark-grey">For solids, unlike fluids/gases, a multi-output machine such as a Packaging Unit or Shredding Unit can directly replace the Stash: placing a converger flush against its output creates output priority.</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c5624772107f24fe.gif" alt="Input / Output / Merge Priority Theory: A Brief Explanation"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fe0d488ade871fd6.gif" alt="Input / Output / Merge Priority Theory: A Brief Explanation"></p><p>For more complex cases: <a href="/endfield-skydoc/introduction-to-analyzing-endfield-logistics-bugs">Introduction to Analyzing Endfield Logistics Bugs</a>.</p><p><span class="mark-grey">#jnk: This priority acts instantaneously. Two input belts whose combined average flow is more than one full belt will not simply overflow into one full belt plus one partly filled belt. When two items arrive simultaneously, this structure cannot hold the extra item back and output it later when no items arrive. For overflow that is not instantaneous, see </span><a href="/endfield-skydoc/a-stable-overflow-router-for-unstable-flow">A Stable Overflow Device for Unstable Flow</a>.</p><p><span id="source-block-YaKEdAbnDnMx5Vv6e3oH6j"></span></p><h2 id="merge-priority-splitter–converger" tabindex="-1">Merge Priority: Splitter–Converger <a class="header-anchor" href="#merge-priority-splitter–converger" aria-label="Permalink to &quot;Merge Priority: Splitter–Converger&quot;">​</a></h2><p>If a splitter output is flush against a converger input, the converger gains merge priority: the upstream component placed first has priority. If that first component is not a splitter, it services later non-splitter components round-robin.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-82eba631c9f66e78.gif" alt="Input / Output / Merge Priority Theory: A Brief Explanation"></p><p><span class="mark-grey">More detail on priority and connection order: when a Converger input directly touches a Splitter output, priority is assigned by connection order; non-Splitters share the higher priority; reaction-tank outputs and Depot Unloaders always have the lowest priority.</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6bdec967d51a7203.q90-e7f9b2fc3166ab03.webp" alt="Input / Output / Merge Priority Theory: A Brief Explanation"></p><p>For more complex cases, see: <a href="/endfield-skydoc/introduction-to-analyzing-endfield-logistics-bugs#source-block-htoulawLZUlJ1UaMq7o6xO">Introduction to Analyzing Endfield Logistics Bugs</a></p><p><span id="source-block-SJwMhKtD8ELVC0QucYr9nJ"></span></p><h2 id="output-input-priority-through-normal-round-robin-servicing" tabindex="-1">Output / Input Priority through Normal Round-Robin Servicing <a class="header-anchor" href="#output-input-priority-through-normal-round-robin-servicing" aria-label="Permalink to &quot;Output / Input Priority through Normal Round-Robin Servicing&quot;">​</a></h2><p>Output priority: Conduit Outlet Manifold A supplies 120/min Xiragen. Its ports connect to Conduit Inlets B consuming 30/min and C consuming 120/min. B&#39;s demand is satisfied first. Strictly, if B/C&#39;s consumption is below 1/2 of A&#39;s flow, supply is guaranteed. The factor 1/2 arises because when both ports are unblocked the manifold outputs round-robin, equally over sufficiently long time. This is output priority in a broad sense.</p><p>Input priority: Conduit Inlet Manifold A consumes 120/min Xiragen. Its ports connect to Conduit Outlets B supplying 30/min and C supplying 120/min. B&#39;s output is consumed first. Strictly, if B/C&#39;s input is below 1/2 of A&#39;s flow, all of it is consumed. The factor 1/2 arises because when both ports are blocked the manifold inputs round-robin, equally over sufficiently long time. This is input priority in a broad sense. [The source calls B/C “Conduit Inlets” in this latter strict statement.]</p><p>For a more systematic explanation, I cite kokobird&#39;s <a href="/endfield-skydoc/2-5-is-a-stash-not-just-a-special-splitter">2.5 Is a Stash Not Just a Special Splitter? (Core Content ⭐)</a>.</p><p><span id="source-block-cSE6qgeFTPC10fGIVcuoTG"></span></p><h2 id="input-priority-broken-by-the-four-item-stall-output-lag" tabindex="-1">Input Priority Broken by the Four-Item Stall (Output Lag) <a class="header-anchor" href="#input-priority-broken-by-the-four-item-stall-output-lag" aria-label="Permalink to &quot;Input Priority Broken by the Four-Item Stall (Output Lag)&quot;">​</a></h2><p>A splitter&#39;s four-item stall may degrade priority into incomplete priority. If priority breaks and, with upstream blocked, the priority side receives 2 fluid units while the secondary side outputs 1—instead of the normal round-robin of 1 for you and 1 for me—the stall is likely occurring. There are two simple repairs, whose sufficiency is still being verified:</p><p>Details: <a href="/endfield-skydoc/introduction-to-analyzing-endfield-logistics-bugs">Introduction to Analyzing Endfield Logistics Bugs</a>.</p></div>',1)])])}const g=e(n,[["render",a]]);export{h as __pageData,g as default};
